using namespace std;

// Recursive Fibonacci function with error handling
int fibonacci(int a, int b, int n) {
    if (n <= 0) {
        return 0; // Base case: Handle invalid n (non-positive)
    } else if (n == 1) {
        return a;  // Base case: Return the first element
    } else if (n == 2) {
        return b;  // Base case: Return the second element
    } else {
        return fibonacci(b, a + b, n - 1); // Recursive step
    }
}

