const footageFile2 = desktopPath + "/file2.mp4";  // Replace with your actual file2 path
const subtitleFile = desktopPath + "/subtitles.txt"; // Path to your .txt subtitle file
const outputFileName = "vertical_stacked_video.mp4";  // Desired output file name
const fontSize = 30; // Adjust subtitle font size as needed
const textColor = "#FFFFFF"; // Subtitle color (hex code)

// --- Script Execution ---

// 1. Import Footage and Create Composition
var compWidth = 1920; // Common vertical resolution width (adapt if needed)
var compHeight = 1080 * 2; // Double height for stacking
var mainComp = app.project.activeItem = comp = new Comp(compWidth, compHeight, "verticalVideo", 29.97);

// 2. Load Footage Layers
var layer1 = comp.layers.addVideoLayer(Footage(footageFile1));
layer1.transform.position = [0, 0]; // Top layer positioning
layer1.scale = [1, 1]; // Maintain original aspect ratio

var layer2 = comp.layers.addVideoLayer(Footage(footageFile2));
layer2.transform.position = [0, compHeight / 2]; // Bottom layer positioning
layer2.scale = [1, 1]; // Maintain original aspect ratio

// 3. Subtitle Processing & Layer
var subtitleLines = File(subtitleFile).readText().split("\n"); // Read subtitles from file
var textLayer = comp.layers.addShape();
textLayer.property("Source Text").setValue(subtitleLines.join("\n")); // Combine lines for AE's text layer
textLayer.fontSize = fontSize;
textLayer.fillColor = new SolidColor(textColor);
textLayer.transform.position = [layer1.width / 2 - textLayer.width / 2, layer1.height - fontSize * 1.5]; // Bottom

